fn all_names(deps: Map[Str, List[Str]]) -> List[Str] {
  var names: List[Str] = []
  for entry in deps.entries() {
    if not names.contains(entry.key) {
      names = names.push(entry.key)
    }
    for d in entry.value {
      if not names.contains(d) {
        names = names.push(d)
      }
    }
  }
  return names.sort()
}

fn deps_of(deps: Map[Str, List[Str]], task: Str) -> List[Str] {
  let none_list: List[Str] = []
  return deps.get(task).unwrap_or(none_list)
}

pub fn topo(deps: Map[Str, List[Str]]) -> Result[List[Str], Str] {
  var remaining = all_names(deps)
  var order: List[Str] = []
  while remaining.len() > 0 {
    let finished = order
    let pick = remaining.find(fn(cand) => deps_of(deps, cand).all(fn(d) => finished.contains(d)))
    match pick {
      Some(chosen) => {
        order = order.push(chosen)
        remaining = remaining.filter(fn(x) => x != chosen)
      },
      None => { return Err("cycle") },
    }
  }
  return Ok(order)
}
